INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`, `updated_by`, `updated_at`) VALUES (9,'bn','{\"body\": \"মোটরসাইকেল ও তিন চাকার যানবাহন নিষিদ্ধ। রওনা হওয়ার আগে গতিসীমা ও বন্ধ থাকা অংশ সম্পর্কে জেনে নিন।\", \"heading\": \"যাত্রার আগে\", \"primaryHref\": \"travel/rules\", \"primaryLabel\": \"সড়ক বিধি\", \"secondaryHref\": \"travel/status\", \"secondaryLabel\": \"আজ কী খোলা আছে\"}','published',NULL,'2026-09-05 07:01:18');
