INSERT IGNORE INTO `content` (`section_key`, `data`, `updated_at`) VALUES ('home.callout','{\"text\": \"Discover how the Dhaka Bypass Expressway is creating connections and transforming communities with state-of-the-art infrastructure.\", \"heading\": \"Experience the Future of Transportation in Bangladesh\", \"primaryCta\": {\"href\": \"/virtual-tour\", \"label\": \"Take a Tour\"}, \"secondaryCta\": {\"href\": \"/contact\", \"label\": \"Contact Us\"}}','2026-09-05 07:01:17');
INSERT IGNORE INTO `content` (`section_key`, `data`, `updated_at`) VALUES ('home.economicImpact','{\"cta\": {\"href\": \"/economic-impact\", \"label\": \"Detailed Economic Studies\"}, \"image\": {\"alt\": \"Dhaka Bypass Expressway\", \"src\": \"/eco-eff.webp\"}, \"heading\": \"Economic Impact\", \"metrics\": [{\"icon\": \"users\", \"color\": \"blue\", \"label\": \"Local Jobs Created\", \"value\": \"1,000+\"}, {\"icon\": \"award\", \"color\": \"orange\", \"label\": \"Travel Time Reduction\", \"value\": \"75%\"}, {\"icon\": \"trending-up\", \"color\": \"blue\", \"label\": \"Total Investment\", \"value\": \"US$412M\"}, {\"icon\": \"truck\", \"color\": \"orange\", \"label\": \"National Routes Connected\", \"value\": \"4 Highways\"}], \"paragraphs\": [\"The Dhaka Bypass Expressway is having significant economic impact. As a connector that intelligently links production zones with ports, it enhances Bangladesh\'s supply chain reliability and trade competitiveness by creating an efficient freight corridor linking manufacturing and export processing zones in northern Bangladesh to Chattogram Port.\", \"Upon completion, the expressway will cut journey time from Gazipur to Madanpur from 2 hours to just 30 minutes – a 75% reduction that translates directly to fuel savings, lower vehicle operating costs, and improved productivity for businesses. Diverting traffic from city roads will save millions of dollars in lost time and fuel that would otherwise be spent in traffic jams.\", \"The project has already created 1,000+ jobs during construction with this number expected to double to approximately 2,000 at peak construction. The project represents a total investment of around ৳3,585-3,723 crore (approximately US$350-412 million) into Bangladesh\'s infrastructure, mobilizing both domestic and foreign capital under an innovative PPP structure.\", \"Areas along the bypass route (Gazipur, Narayanganj, Narsingdi districts) are experiencing new economic opportunities, with improved connectivity attracting industrial parks, warehouses, and real estate development. The expressway aligns with the Asian Highway network and supports the Greater Dhaka urban expansion, thereby decentralizing growth from the capital.\"], \"subheading\": \"Creating Sustainable Value for Bangladesh\'s Growth\"}','2026-09-05 07:01:17');
INSERT IGNORE INTO `content` (`section_key`, `data`, `updated_at`) VALUES ('home.hero','{\"logo\": \"/logo.webp\", \"headline\": \"Connecting Bangladesh\'s Infrastructure\", \"primaryCta\": {\"href\": \"#overview\", \"label\": \"Learn More\"}, \"subheadline\": \"Building the first fully access-controlled expressway to transform national connectivity\", \"routeMapImage\": \"/map.webp\", \"routeMapButton\": \"View Route Map\", \"backgroundImage\": \"/bg-hero.webp\"}','2026-09-05 07:01:17');
INSERT IGNORE INTO `content` (`section_key`, `data`, `updated_at`) VALUES ('home.meta','{\"title\": \"Dhaka Bypass Expressway - Bangladesh\'s First Fully Access-Controlled Highway\", \"description\": \"Official website of the Dhaka Bypass Expressway project, spanning 48km and connecting major national highways around Dhaka.\"}','2026-09-05 07:01:17');
INSERT IGNORE INTO `content` (`section_key`, `data`, `updated_at`) VALUES ('home.overview','{\"cta\": {\"href\": \"/project/\", \"label\": \"Complete Project Details\"}, \"image\": {\"alt\": \"Dhaka Bypass Expressway\", \"src\": \"/bypass-ex.webp\"}, \"stats\": [{\"icon\": \"truck\", \"color\": \"blue\", \"label\": \"Total Expressway Length\", \"value\": \"48 km\"}, {\"icon\": \"clock\", \"color\": \"orange\", \"label\": \"In Travel Time\", \"value\": \"75% Reduction\"}, {\"icon\": \"file-text\", \"color\": \"blue\", \"label\": \"Road Project in Bangladesh\", \"value\": \"1st PPP\"}, {\"icon\": \"trending-up\", \"color\": \"orange\", \"label\": \"Concession Period\", \"value\": \"25 Years\"}], \"heading\": \"Project Overview\", \"inlineLink\": {\"href\": \"/about-project\", \"label\": \"Learn more about the project\"}, \"paragraphs\": [\"The Dhaka Bypass Expressway is Bangladesh\'s first fully enclosed highway, spanning 48 kilometers from Joydebpur (Gazipur) to Madanpur (Narayanganj). This vital arterial route connects four national highways (N1, N2, N3, N4) and provides an efficient pathway around the capital, linking northern industrial areas to southern ports.\", \"Developed by Dhaka Bypass Expressway Development Company (DBEDC), the project represents a landmark public-private partnership between Sichuan Road & Bridge Group (SRBG), Shamim Enterprise Ltd (SEL), and UDC Construction Ltd. This consortium is responsible for the design, build, finance, operate, and maintain (DBFOM) tasks under a 25-year concession agreement.\", \"Upon completion in July 2025, this state-of-the-art expressway will transform travel around Dhaka with four main carriageways, service roads on both sides, and fully grade-separated interchanges, cutting the journey time from Gazipur to Madanpur from 2 hours to just 30 minutes.\"], \"subheading\": \"Transforming Bangladesh\'s Transportation Infrastructure\", \"imageCaption\": {\"title\": \"Fully Access-Controlled Expressway\", \"eyebrow\": \"Bangladesh\'s First\"}}','2026-09-05 07:01:17');
INSERT IGNORE INTO `content` (`section_key`, `data`, `updated_at`) VALUES ('home.route','{\"cta\": {\"href\": \"/expressway-route\", \"label\": \"Explore The Route Map\"}, \"image\": {\"alt\": \"Dhaka Bypass Expressway\", \"src\": \"/map.webp\"}, \"heading\": \"Expressway Route\", \"paragraphs\": [\"The Dhaka Bypass Expressway spans 48 kilometers from Joydebpur (Gazipur) in the north to Madanpur (Narayanganj) in the south. This strategic route connects four major national highways (N1, N2, N3, N4), creating an uninterrupted corridor around eastern Dhaka.\", \"Key interchanges include Vogra, Mirer Bazar, Purbachal, Bhulta, and Madanpur, providing crucial connectivity to industrial zones, new urban developments, and transportation networks. The expressway features 12 bridges, 7 flyovers, and 27 underpasses.\"], \"subheading\": \"Connecting Communities and Commerce\"}','2026-09-05 07:01:17');
INSERT IGNORE INTO `content` (`section_key`, `data`, `updated_at`) VALUES ('page.chinese-contribution','{\"t1\": \"Chinese Contribution\", \"t2\": \"Technical innovation, financial investment, and expertise from China helping to transform Bangladesh\'s infrastructure\", \"t3\": \"Learn More\", \"t4\": \"Key Contributions\", \"t5\": \"China-Bangladesh Cooperation\", \"t6\": \"The Dhaka Bypass Expressway project represents a landmark achievement in China-Bangladesh cooperation, bringing together Chinese investment, technical expertise, and experience with local Bangladeshi knowledge and resources.\", \"t7\": \"Led by Sichuan Road & Bridge Group (SRBG) as the majority partner with a 60% stake in the project company, Chinese contribution encompasses financing, engineering expertise, advanced construction methods, and knowledge transfer that is helping to transform Bangladesh\'s infrastructure landscape.\", \"t8\": \"This partnership demonstrates how the Belt and Road Initiative is creating practical benefits through infrastructure development. By introducing innovative technologies like semi-rigid pavement and reinforced retaining walls for the first time in Bangladesh, Chinese partners are not just building a road but establishing new standards for infrastructure throughout the country.\", \"t9\": \"Landmark Partnership\", \"t10\": \"The first major road PPP project in Bangladesh with Chinese investment\", \"t11\": \"60%\", \"t12\": \"Equity Stake\", \"t13\": \"$412M\", \"t14\": \"Financing\", \"t15\": \"Investment Impact\", \"t16\": \"$\", \"t17\": \"412\", \"t18\": \"M\", \"t19\": \"Total Project Investment\", \"t20\": \"60\", \"t21\": \"%\", \"t22\": \"SRBG Equity Stake\", \"t23\": \"1000\", \"t24\": \"+\", \"t25\": \"Jobs Created\", \"t26\": \"Key Chinese Contributions\", \"t27\": \"China\'s multifaceted contribution to the Dhaka Bypass Expressway encompasses financing, technology, expertise, and community support\", \"t28\": \"Financial Investment\", \"t29\": \"SRBG holds a 60% majority stake in the project, representing the largest share of private investment. China Development Bank provided a crucial ৳1,614 crore loan (approximately $190 million) to support the project\'s financing.\", \"t30\": \"Lead private investor with approximately $240 million in equity investment\", \"t31\": \"China Development Bank provided crucial long-term financing\", \"t32\": \"Mobilized total investment package worth $412 million\", \"t33\": \"Facilitated financial close in April 2021\", \"t34\": \"Technical Expertise\", \"t35\": \"SRBG introduced advanced Chinese engineering techniques, particularly the semi-rigid pavement technology and reinforced retaining wall systems, significantly enhancing construction quality and durability.\", \"t36\": \"Implemented semi-rigid pavement technology for the first time in Bangladesh\", \"t37\": \"Introduced innovative reinforced retaining wall systems\", \"t38\": \"Brought international quality control standards\", \"t39\": \"Integrated advanced traffic management systems and safety features\", \"t40\": \"Construction Management\", \"t41\": \"Chinese engineering teams provided comprehensive project management expertise, from initial design through construction planning and execution, bringing international standards to Bangladesh\'s road infrastructure.\", \"t42\": \"Established modern project management systems\", \"t43\": \"Implemented efficient construction planning and scheduling\", \"t44\": \"Developed comprehensive environmental management plans\", \"t45\": \"Applied advanced quality assurance and testing protocols\", \"t46\": \"Knowledge Transfer\", \"t47\": \"A key component of Chinese contribution has been extensive knowledge transfer, with training programs for Bangladeshi engineers both in Bangladesh and China, creating lasting capacity within the local engineering community.\", \"t48\": \"Organized technical training programs for Bangladeshi engineers in China\", \"t49\": \"Established on-site training for local workers and engineers\", \"t50\": \"Transferred modern highway construction methodologies\", \"t51\": \"Shared operations and maintenance knowledge for long-term sustainability\", \"t52\": \"Belt and Road Initiative\", \"t53\": \"The Dhaka Bypass Expressway is a flagship project under China\'s Belt and Road Initiative in Bangladesh, representing practical cooperation that strengthens connectivity and enhances bilateral relations.\", \"t54\": \"Featured as a practical cooperation project at the Third Belt and Road Forum\", \"t55\": \"Demonstrates practical implementation of the BRI concept\", \"t56\": \"Supports regional connectivity across South Asia\", \"t57\": \"Strengthens China-Bangladesh economic and diplomatic relations\", \"t58\": \"Social Responsibility\", \"t59\": \"Beyond construction, SRBG has demonstrated corporate social responsibility through community outreach, donating to local schools, supporting orphanages, and providing COVID-19 relief supplies.\", \"t60\": \"Donated multimedia classrooms to primary schools\", \"t61\": \"Provided support to local orphanages\", \"t62\": \"Contributed COVID-19 prevention supplies during the pandemic\", \"t63\": \"Implemented employee welfare programs for local workers\", \"t64\": \"Case Study: Semi-Rigid Pavement Technology\", \"t65\": \"Introducing revolutionary road construction techniques to Bangladesh\", \"t66\": \"Technology Transfer\", \"t67\": \"One of the most significant Chinese contributions to the Dhaka Bypass Expressway project has been the introduction of semi-rigid pavement technology to Bangladesh. This innovative construction method combines the flexibility of asphalt with the strength of concrete to create a more durable and longer-lasting road surface.\", \"t68\": \"SRBG has not only implemented this technology but has provided comprehensive training to Bangladeshi engineers, both through specialized programs in China and hands-on training at the project site. This knowledge transfer will have lasting benefits for infrastructure development throughout Bangladesh.\", \"t69\": \"Benefits for Bangladesh\", \"t70\": \"Increased Durability\", \"t71\": \"Extends road life by up to 30% compared to conventional methods\", \"t72\": \"Local Materials\", \"t73\": \"Utilizes Bangladesh\'s abundant fine sand resources effectively\", \"t74\": \"Reduced Maintenance\", \"t75\": \"Lower lifecycle costs through less frequent repairs\", \"t76\": \"Environmental Benefits\", \"t77\": \"Reduces use of traditional brick materials, promoting sustainability\", \"t78\": \"The semi-rigid pavement technology introduced by SRBG is perfectly suited to Bangladesh\'s climate, geological conditions, and available materials. This innovation will have lasting impact on our infrastructure development.\", \"t79\": \"— Bangladeshi Highway Engineering Expert\", \"t80\": \"Belt and Road Initiative\", \"t81\": \"Part of the Belt and Road Initiative\", \"t82\": \"The Dhaka Bypass Expressway stands as a flagship project of the Belt and Road Initiative (BRI) in Bangladesh, representing practical cooperation that creates tangible benefits for the local population and economy.\", \"t83\": \"As highlighted at the Third Belt and Road Forum, this project exemplifies how Chinese expertise and investment can work within local frameworks to deliver infrastructure that meets international standards while respecting local needs and conditions.\", \"t84\": \"By improving connectivity not only within Bangladesh but also to the broader regional transportation network, the expressway contributes to the core BRI goal of enhancing interconnectivity across Asia. The project demonstrates how the initiative creates practical partnerships that benefit both China and participating countries.\", \"t85\": \"BRI Benefits\", \"t86\": \"Enhances regional connectivity across South Asia\", \"t87\": \"Creates a model for future infrastructure cooperation\", \"t88\": \"Facilitates technology and knowledge transfer\", \"t89\": \"Strengthens economic and diplomatic relations\", \"t90\": \"Knowledge Transfer\", \"t91\": \"Building capacity and expertise within Bangladesh\'s infrastructure sector\", \"t92\": \"Training Programs\", \"t93\": \"SRBG has organized comprehensive training programs for Bangladeshi engineers, both in China and on-site. These programs have covered advanced road construction techniques, quality control methods, and project management practices.\", \"t94\": \"Through this knowledge transfer, local engineers and workers gain valuable skills that will benefit future infrastructure projects throughout Bangladesh, creating a lasting legacy beyond the expressway itself.\", \"t95\": \"Technology Adoption\", \"t96\": \"The project has introduced multiple advanced technologies to Bangladesh\'s infrastructure sector for the first time, including semi-rigid pavement construction, reinforced retaining walls, and modern traffic management systems.\", \"t97\": \"This technology adoption helps Bangladesh modernize its infrastructure capabilities, setting new standards for future projects and enhancing the country\'s overall engineering capacity.\", \"t98\": \"50\", \"t99\": \"+\", \"img1\": \"/friends.webp\", \"img2\": \"/road.webp\", \"img3\": \"/hma.webp\", \"img4\": \"/cbri.webp\", \"img5\": \"/DSC02396.webp\", \"img6\": \"/DSC02357.webp\", \"img7\": \"/IMG_6282.webp\", \"t100\": \"Engineers Trained\", \"t101\": \"2\", \"t102\": \"New Technologies Introduced\", \"t103\": \"Technical Documentation\", \"t104\": \"Complete technical documentation and manuals have been provided in both English and Bengali, creating a valuable reference resource for future infrastructure projects in Bangladesh.\", \"t105\": \"Social Responsibility\", \"t106\": \"Contributing to communities beyond infrastructure\", \"t107\": \"Educational Support\", \"t108\": \"SRBG has donated multimedia classrooms to primary schools near the expressway, enhancing educational facilities for local children and supporting digital literacy.\", \"t109\": \"Impact:\", \"t110\": \"Improved educational resources for hundreds of students\", \"t111\": \"Pandemic Support\", \"t112\": \"During the COVID-19 pandemic, SRBG donated essential medical supplies to local government agencies, contributing to the community\'s health and safety during a critical time.\", \"t113\": \"Impact:\", \"t114\": \"Provide the most timely assistance when the epidemic prevention situation is severe and epidemic prevention materials are in short supply.\", \"t115\": \"Community Outreach\", \"t116\": \"The project team has organized regular visits to local orphanages and vulnerable communities, providing both material support and engaging in cultural exchange activities.\", \"t117\": \"Impact:\", \"t118\": \"Built lasting relationships with local communities\", \"t119\": \"Discover More About the Project\", \"t120\": \"Learn about other aspects of the Dhaka Bypass Expressway\", \"t121\": \"Meet the Stakeholders\", \"t122\": \"Project Overview\"}','2026-09-05 07:01:17');
INSERT IGNORE INTO `content` (`section_key`, `data`, `updated_at`) VALUES ('page.contact','{\"t1\": \"Contact Us\", \"t2\": \"Get in touch with the Dhaka Bypass Expressway Development Company for inquiries, partnerships, or more information.\", \"t3\": \"Send us a message\", \"t4\": \"Your Name\", \"t5\": \"Email Address\", \"t6\": \"Subject\", \"t7\": \"Message\", \"t8\": \"Send Message\", \"t9\": \"Contact Information\", \"t10\": \"Address\", \"t11\": \"Road 6, House 15, Block K\", \"t12\": \"Baridhara, Dhaka-1212, Bangladesh\", \"t13\": \"Email\", \"t14\": \"info@dbedc.com\", \"t15\": \"Phone\", \"t16\": \"+880 12345-6789\"}','2026-09-05 07:01:17');
INSERT IGNORE INTO `content` (`section_key`, `data`, `updated_at`) VALUES ('page.economic-impact','{\"t1\": \"Economic Impact\", \"t2\": \"How the Dhaka Bypass Expressway is transforming Bangladesh\'s economy and infrastructure\", \"t3\": \"Driving Economic Growth\", \"t4\": \"The Dhaka Bypass Expressway is creating substantial economic impacts through improved connectivity, reduced travel times, and opening new opportunities for trade and commerce throughout Bangladesh. The project represents a cornerstone development in the nation\'s transportation infrastructure.\", \"t5\": \"0\", \"t6\": \"%\", \"t7\": \"GDP Growth Impact\", \"t8\": \"0\", \"t9\": \"%\", \"t10\": \"Travel Time Reduction\", \"t11\": \"0\", \"t12\": \"+\", \"t13\": \"Jobs Created\", \"t14\": \"$\", \"t15\": \"0\", \"t16\": \"M\", \"t17\": \"Total Investment\", \"t18\": \"Enhanced Trade & Commerce\", \"t19\": \"The Dhaka Bypass Expressway creates a vital economic corridor that enhances trade flow between key industrial zones and major ports. By directly connecting Gazipur\'s manufacturing hubs with southern ports via Narayanganj, the expressway reduces freight transit times by up to 75%.\", \"t20\": \"This improved connectivity is projected to increase exports by 0.8% of GDP as transportation costs decrease and reliability increases, making Bangladeshi products more competitive in global markets.\", \"t21\": \"Key Benefits for Trade\", \"t22\": \"Reduced transport costs (estimated 15-20% reduction)\", \"t23\": \"Improved just-in-time delivery capabilities\", \"t24\": \"Enhanced access to global markets via Chattogram Port\", \"t25\": \"Economic Growth Metrics\", \"t26\": \"Freight Transport Efficiency\", \"t27\": \"+65%\", \"t28\": \"Regional Business Growth\", \"t29\": \"+42%\", \"t30\": \"Industrial Land Value Increase\", \"t31\": \"+85%\", \"t32\": \"New Business Establishments\", \"t33\": \"+120\", \"t34\": \"Employment & Skills Development\", \"t35\": \"The Dhaka Bypass Expressway project is generating substantial employment opportunities while facilitating technology and knowledge transfer to Bangladesh\'s infrastructure sector.\", \"t36\": \"Direct Employment\", \"t37\": \"During peak construction, the project employs over 2,000 workers across various skill levels, from engineers to construction workers.\", \"t38\": \"2,000+\", \"t39\": \"Direct Jobs Created\", \"t40\": \"Indirect Employment\", \"t41\": \"The economic activity generated by the expressway creates an estimated 10,000 indirect jobs in supporting industries and services.\", \"t42\": \"10,000+\", \"t43\": \"Indirect Jobs Supported\", \"t44\": \"Skills Development\", \"t45\": \"Comprehensive training programs are equipping the local workforce with specialized skills in modern construction techniques.\", \"t46\": \"500+\", \"t47\": \"Workers Trained in New Technologies\", \"t48\": \"Regional Development Impact\", \"t49\": \"The expressway is transforming areas along its route, creating new economic hubs and opportunities\", \"t50\": \"Urban Development Zones\", \"t51\": \"Areas adjacent to the expressway are experiencing significant urban development. The Purbachal New Town project, directly accessible from the expressway, is becoming a major satellite city with commercial and residential developments.\", \"t52\": \"Key Growth Areas:\", \"t53\": \"Purbachal Economic Zone - 46% land value increase\", \"t54\": \"Gazipur Industrial Corridor - 38% business growth\", \"t55\": \"Narayanganj Logistics Hub - 52% capacity expansion\", \"t56\": \"Long-Term Economic Benefits\", \"t57\": \"The economic impact extends beyond immediate construction benefits. The expressway creates a foundation for sustainable economic growth throughout eastern Bangladesh over the next 25+ years.\", \"t58\": \"Projected Long-Term Effects:\", \"t59\": \"Decentralization of economic activity from Dhaka core\", \"t60\": \"Creation of specialized industrial clusters along the route\", \"t61\": \"Enhanced property values and local tax revenues\", \"t62\": \"Integration with other planned infrastructure projects\", \"t63\": \"Explore More About Dhaka Bypass Expressway\", \"t64\": \"Discover how this transformative project is connecting communities and driving economic growth\", \"t65\": \"Project Details\", \"t66\": \"Routes & Facilities\", \"img1\": \"/eco-eff.webp\"}','2026-09-05 07:01:17');
INSERT IGNORE INTO `content` (`section_key`, `data`, `updated_at`) VALUES ('page.gallery','{\"intro\": \"Visual documentation of the Dhaka Bypass Expressway construction progress and milestones.\", \"heading\": \"Project Gallery\"}','2026-09-05 07:01:17');
INSERT IGNORE INTO `content` (`section_key`, `data`, `updated_at`) VALUES ('page.latest-updates','{\"t1\": \"Latest Updates\", \"t2\": \"Stay informed with the latest news and updates about the Dhaka Bypass Expressway project\", \"t3\": \"Latest News Coverage\", \"t4\": \"Operations\", \"t5\": \"April 15, 2025\", \"t6\": \"Dhaka Bypass Expressway Facilitates Unhindered Eid Travels\", \"t7\": \"The newly opened section of the Dhaka Bypass Expressway has significantly improved travel experience during Eid, providing unhindered movement for thousands of travelers.\", \"t8\": \"New Age Bangladesh\", \"t9\": \"Read More\", \"t10\": \"Infrastructure\", \"t11\": \"April 8, 2025\", \"t12\": \"Dhaka Bypass Expressway to Open Partly on 1 May\", \"t13\": \"The 48-kilometre Dhaka bypass expressway is set to open partly on 1 May to facilitate smoother operation for buses, trucks, and other vehicles from northern and western regions to southern and eastern regions.\", \"t14\": \"The Business Standard\", \"t15\": \"Read More\", \"t16\": \"Transport\", \"t17\": \"April 5, 2025\", \"t18\": \"18km Dhaka Bypass Expressway Opened to Traffic Ahead of Eid\", \"t19\": \"A significant portion of the Dhaka Bypass Expressway has been opened to traffic ahead of Eid celebrations, marking a major milestone in the project\'s development.\", \"t20\": \"The Business Standard\", \"t21\": \"Read More\", \"t22\": \"Development\", \"t23\": \"March 30, 2025\", \"t24\": \"Dhaka Bypass Expressway to be Operational by July\", \"t25\": \"The entire Dhaka Bypass Expressway project is scheduled to be fully operational by July, promising to revolutionize transportation around the capital.\", \"t26\": \"Dhaka Tribune\", \"t27\": \"Read More\", \"t28\": \"Partnership\", \"t29\": \"December 6, 2018\", \"t30\": \"Government of Bangladesh Signs PPP Contract for Dhaka Bypass\", \"t31\": \"The Government of Bangladesh has signed a landmark public-private partnership contract for the development of the Dhaka Bypass Expressway project.\", \"t32\": \"Asian Development Bank\", \"t33\": \"Read More\", \"t34\": \"Project Info\", \"t35\": \"Ongoing\", \"t36\": \"Dhaka Bypass Project Details\", \"t37\": \"Comprehensive information about the Dhaka Bypass project, including technical specifications, financial arrangements, and implementation timeline.\", \"t38\": \"PPP Authority Bangladesh\", \"t39\": \"Read More\", \"t40\": \"Photo Gallery\", \"t41\": \"Stay Updated with DBEDC\", \"t42\": \"Subscribe to our newsletter to receive the latest updates about the Dhaka Bypass Expressway project\", \"t43\": \"Subscribe\", \"img1\": \"/road.webp\", \"img2\": \"/photo/1.webp\", \"img3\": \"/photo/2.webp\", \"img4\": \"/photo/3.webp\", \"img5\": \"/photo/4.webp\", \"img6\": \"/photo/5.webp\", \"img7\": \"/photo/6.webp\", \"img8\": \"/photo/7.webp\", \"img9\": \"/photo/8.webp\", \"img10\": \"/photo/9.webp\", \"img11\": \"/photo/10.webp\", \"img12\": \"/photo/11.webp\", \"img13\": \"/photo/12.webp\", \"img14\": \"/photo/13.webp\", \"img15\": \"/photo/14.webp\", \"img16\": \"/photo/15.webp\", \"img17\": \"/photo/16.webp\", \"img18\": \"/photo/17.webp\", \"img19\": \"/photo/18.webp\", \"img20\": \"/photo/19.webp\", \"img21\": \"/photo/20.webp\", \"img22\": \"/photo/21.webp\", \"img23\": \"/photo/22.webp\", \"img24\": \"/photo/23.webp\", \"img25\": \"/photo/24.webp\", \"img26\": \"/photo/25.webp\", \"img27\": \"/photo/26.webp\", \"img28\": \"/photo/27.webp\", \"img29\": \"/photo/28.webp\", \"img30\": \"/photo/29.webp\", \"img31\": \"/photo/30.webp\", \"img32\": \"/photo/31.webp\", \"img33\": \"/photo/32.webp\", \"img34\": \"/photo/33.webp\", \"img35\": \"/photo/34.webp\", \"img36\": \"/photo/35.webp\", \"img37\": \"/photo/36.webp\"}','2026-09-05 07:01:17');
INSERT IGNORE INTO `content` (`section_key`, `data`, `updated_at`) VALUES ('page.notFound','{\"code\": \"404\", \"text\": \"The page you\'re looking for doesn\'t exist or has been moved.\", \"ctaHref\": \"/\", \"heading\": \"Page Not Found\", \"ctaLabel\": \"Back to Home\"}','2026-09-05 07:01:17');
INSERT IGNORE INTO `content` (`section_key`, `data`, `updated_at`) VALUES ('page.project','{\"t1\": \"Dhaka Bypass Expressway\", \"t2\": \"Bangladesh\'s first fully access-controlled expressway, creating a strategic corridor around eastern Dhaka\", \"t3\": \"Project Overview\", \"t4\": \"View Route Map\", \"t5\": \"Project Overview\", \"t6\": \"About the Project\", \"t7\": \"The Dhaka Bypass Expressway is a transformative 48.07-kilometer highway that provides a strategic corridor around eastern Dhaka, connecting major national highways N1 (Dhaka-Chattogram), N2 (Dhaka-Sylhet), N3 (Dhaka-Mymensingh), and N4 (Dhaka-Tangail/Northwest).\", \"t8\": \"Developed under a Public-Private Partnership (PPP) model, this project represents a significant milestone in Bangladesh\'s infrastructure development. The project follows a Design, Build, Finance, Operate, Maintain, and Transfer (DBFOMT) arrangement with a 25-year concession period.\", \"t9\": \"When completed, the expressway will reduce travel time between Joydebpur and Madanpur from over 2 hours to approximately 40 minutes, significantly improving connectivity and economic prospects for the region.\", \"t10\": \"Current Status\", \"t11\": \"Overall Progress\", \"t12\": \"69.11\", \"t13\": \"%\", \"t14\": \"Category Breakdown:\", \"t15\": \"General\", \"t16\": \"93.9\", \"t17\": \"%\", \"t18\": \"Earthwork\", \"t19\": \"82.89\", \"t20\": \"%\", \"t21\": \"Pavement\", \"t22\": \"53.95\", \"t23\": \"%\", \"t24\": \"Foundation\", \"t25\": \"100\", \"t26\": \"%\", \"t27\": \"Structure\", \"t28\": \"90.9\", \"t29\": \"%\", \"t30\": \"Incidental\", \"t31\": \"54.21\", \"t32\": \"%\", \"t33\": \"Last updated: December 31, 2024\", \"t34\": \"Key Achievements\", \"t35\": \"Completed Foundations\", \"t36\": \"All foundation work has been completed (100%).\", \"t37\": \"Major Structures Progress\", \"t38\": \"Structural work is at 90.9% completion, including Ulukhula, Nagda, Mir er Bazar, and Dhirasram Overpasses.\", \"t39\": \"Road Construction\", \"t40\": \"Over 31.76 km of embankment fill for the toll road and 40.44 km for service roads completed.\", \"t41\": \"Pavement Layers\", \"t42\": \"Approximately 22 km of asphalt layers (AC-20 & AC-13) completed for toll roads and 28 km for service roads.\", \"t43\": \"Box Culverts\", \"t44\": \"62 out of 73 planned box culverts have been completed.\", \"t45\": \"Project Timeline\", \"t46\": \"2018\", \"t47\": \"PPP Contract Signed\", \"t48\": \"PPP contract was signed in December 2018 between Roads and Highways Department and the DBEDC.\", \"t49\": \"2020\", \"t50\": \"Construction Begins\", \"t51\": \"Initial construction works commenced in November 2020, with final construction officially starting in May 2022 after the Appointed Date was established.\", \"t52\": \"2022\", \"t53\": \"Appointed Date\", \"t54\": \"May 15, 2022 was established as the official Appointed Date, marking the formal commencement of the construction period.\", \"t55\": \"2025\", \"t56\": \"First Section Opening\", \"t57\": \"This section from K4 to K22 was put into trial operation during the Eid-ul-Fitr period from March 27 to April 5.\", \"t58\": \"2025\", \"t59\": \"Second Section Opening\", \"t60\": \"The section from K22 to K35, including service roads, is targeted to open by December 2025.\", \"t61\": \"Project Specifications\", \"t62\": \"Length\", \"t63\": \"48.07 km\", \"t64\": \"Total expressway length from Joydebpur to Madanpur\", \"t65\": \"Main Carriageway\", \"t66\": \"4 Lanes\", \"t67\": \"9.7m width (7.3m + 2.4m shoulder), design speed 80 km/h\", \"t68\": \"Service Roads\", \"t69\": \"2 Lanes\", \"t70\": \"5.8m width (7.3m every 5 km in the RAJUK Section), design speed 50 km/h\", \"t71\": \"Toll Plazas\", \"t72\": \"6\", \"t73\": \"Strategically placed along the expressway\", \"t74\": \"Major Structures\", \"t75\": \"100+\", \"t76\": \"Including 5 river bridges, 3 minor bridges, 4 flyovers, 45 underpasses, and 87 culverts\", \"t77\": \"Contract Period\", \"t78\": \"25 Years\", \"t79\": \"Design, Build, Finance, Operate, Maintain, Transfer (DBFOMT)\", \"t80\": \"Investment\", \"t81\": \"$412 Million\", \"t82\": \"Total initial project investment\", \"t83\": \"Developer\", \"t84\": \"DBEDC\", \"t85\": \"Dhaka Bypass Expressway Development Company\", \"t86\": \"Innovative Semi-Rigid Pavement Technology\", \"t87\": \"Introducing cutting-edge road construction technology to Bangladesh\", \"t88\": \"Semi-Rigid Pavement\", \"t89\": \"A hybrid pavement system combining flexibility and durability\", \"t90\": \"Technical Advantages\", \"t91\": \"High load-bearing capacity for heavy commercial vehicles\", \"t92\": \"Enhanced durability compared to conventional asphalt pavements\", \"t93\": \"Better resistance to rutting and deformation under tropical conditions\", \"t94\": \"Reduced maintenance requirements over the project lifecycle\", \"t95\": \"Construction Process\", \"t96\": \"Advanced techniques for superior road quality and longevity\", \"t97\": \"Process Innovation\", \"t98\": \"Precision thickness control using advanced equipment\", \"t99\": \"Specialized curing techniques to prevent premature cracking\", \"img1\": \"/bypass-ex.webp\", \"img2\": \"/semi.webp\", \"img3\": \"/cp.webp\", \"t100\": \"Continuous quality monitoring during the construction process\", \"t101\": \"Computerized mix design for optimal performance characteristics\", \"t102\": \"Technology Benefits\", \"t103\": \"Extended Lifespan\", \"t104\": \"30+ years of service life compared to 15-20 years for conventional pavements\", \"t105\": \"Cost Efficiency\", \"t106\": \"Higher initial investment but significantly lower lifecycle maintenance costs\", \"t107\": \"Weather Resistance\", \"t108\": \"Superior performance during monsoon seasons and extreme temperature variations\", \"t109\": \"Vision & Mission\", \"t110\": \"Transforming Bangladesh\'s Infrastructure\", \"t111\": \"Our Vision\", \"t112\": \"To transform Bangladesh\'s transportation infrastructure by creating a world-class expressway that serves as a model for future development projects, enhancing connectivity, and supporting economic growth.\", \"t113\": \"We envision a future where modern, sustainable infrastructure empowers Bangladesh\'s continued development, improves quality of life, and positions the country as a hub for regional connectivity.\", \"t114\": \"Our Mission\", \"t115\": \"To deliver a transformative expressway that sets new standards for safety, efficiency, and sustainability in Bangladesh\'s transportation network.\", \"t116\": \"Implementing innovative engineering solutions and technologies\", \"t117\": \"Fostering knowledge transfer and capacity building\", \"t118\": \"Creating opportunities for economic development along the corridor\", \"t119\": \"Experience the Future of Transportation in Bangladesh\", \"t120\": \"Learn more about this transformative project and how it will revolutionize travel around Dhaka.\", \"t121\": \"Explore Route & Facilities\", \"t122\": \"View Economic Impact\"}','2026-09-05 07:01:17');
INSERT IGNORE INTO `content` (`section_key`, `data`, `updated_at`) VALUES ('page.project/overview','{\"t1\": \"Project Overview\", \"t2\": \"Detailed information about the Dhaka Bypass Expressway project, its objectives, and scope.\", \"t3\": \"Project Description\", \"t4\": \"The Dhaka Bypass Expressway is Bangladesh\'s first fully enclosed highway, spanning 48 kilometers from Joydebpur (Gazipur) to Madanpur (Narayanganj). This vital arterial route connects four national highways (N1, N2, N3, N4) and provides an efficient pathway around the capital, linking northern industrial areas to southern ports.\", \"t5\": \"Developed by Dhaka Bypass Expressway Development Company (DBEDC), the project represents a landmark public-private partnership between Sichuan Road & Bridge Group (SRBG), Shamim Enterprise Ltd (SEL), and UDC Construction Ltd. This consortium is responsible for the design, build, finance, operate, and maintain (DBFOM) tasks under a 25-year concession agreement.\", \"t6\": \"Upon completion in July 2025, this state-of-the-art expressway will transform travel around Dhaka with four main carriageways, service roads on both sides, and fully grade-separated interchanges, cutting the journey time from Gazipur to Madanpur from 2 hours to just 30 minutes.\", \"t7\": \"Project Objectives\", \"t8\": \"Create an efficient transportation corridor around Dhaka\", \"t9\": \"Reduce traffic congestion in the capital city\", \"t10\": \"Connect four major national highways\", \"t11\": \"Enhance logistics and supply chain efficiency\", \"t12\": \"Promote economic development in adjoining areas\", \"t13\": \"Introduce modern expressway standards to Bangladesh\", \"t14\": \"Reduce travel time and transportation costs\", \"t15\": \"Improve road safety with controlled access\", \"t16\": \"Technical Specifications\", \"t17\": \"Length\", \"t18\": \"48 kilometers\", \"t19\": \"Lanes\", \"t20\": \"4 lanes (2 in each direction)\", \"t21\": \"Bridges\", \"t22\": \"12 major bridges\", \"t23\": \"Flyovers\", \"t24\": \"7 flyovers\", \"t25\": \"Underpasses\", \"t26\": \"27 underpasses\", \"t27\": \"Service Roads\", \"t28\": \"Both sides, full length\", \"t29\": \"Interchanges\", \"t30\": \"5 major interchanges\", \"t31\": \"Design Speed\", \"t32\": \"80-100 km/h\", \"t33\": \"Project Sections\", \"t34\": \"Overview\", \"t35\": \"Route Map\", \"t36\": \"Technology\", \"t37\": \"Economic Impact\", \"t38\": \"Timeline\", \"t39\": \"Project Documents\", \"t40\": \"Project Brochure\", \"t41\": \"Technical Specifications\", \"t42\": \"Environmental Impact Assessment\", \"t43\": \"Project Timeline\", \"t44\": \"Need More Information?\", \"t45\": \"Contact our project team for detailed information or specific inquiries about the Dhaka Bypass Expressway project.\", \"t46\": \"Contact Us\"}','2026-09-05 07:01:17');
INSERT IGNORE INTO `content` (`section_key`, `data`, `updated_at`) VALUES ('page.routes-facilities','{\"t1\": \"Routes & Facilities\", \"t2\": \"Explore the Dhaka Bypass Expressway\'s strategic route, key locations, toll information, and traveler facilities\", \"t3\": \"Expressway Route\", \"t4\": \"Key Locations\", \"t5\": \"Toll Information\", \"t6\": \"Expressway Facilities\", \"t7\": \"Expressway Route\", \"t8\": \"Currently Open Section (18 km)\", \"t9\": \"Joydebpur\", \"t10\": \"Starting Point (0 km)\", \"t11\": \"Vogra\", \"t12\": \"K3+900\", \"t13\": \"Mirer Bazar\", \"t14\": \"Kanchan\", \"t15\": \"K22+00\", \"t16\": \"Bhulta\", \"t17\": \"Madanpur\", \"t18\": \"End Point (48 km)\", \"t19\": \"N3\", \"t20\": \"N4\", \"t21\": \"N2\", \"t22\": \"N1\", \"t23\": \"N\", \"t24\": \"S\", \"t25\": \"W\", \"t26\": \"E\", \"t27\": \"Legend\", \"t28\": \"Major Interchanges\", \"t29\": \"Operational Section Points\", \"t30\": \"Open Section (18km)\", \"t31\": \"Under Construction\", \"t32\": \"Route Details\", \"t33\": \"The Dhaka Bypass Expressway creates a strategic corridor around eastern Dhaka, connecting four major national highways (N1, N2, N3, N4). This expressway enables travelers to bypass Dhaka\'s congestion, cutting journey time by up to 75%.\", \"t34\": \"Total Length\", \"t35\": \"48 km\", \"t36\": \"Main Lanes\", \"t37\": \"4 Lanes\", \"t38\": \"Service Roads\", \"t39\": \"2×2 Lanes\", \"t40\": \"Current Status\", \"t41\": \"18 km Open\", \"t42\": \"Route Overview\", \"t43\": \"The Dhaka Bypass Expressway is Bangladesh\'s first fully enclosed highway, serving as a major arterial route around Dhaka. It starts near Kodda (Gazipur) and terminates at Madanpur, where it meets the Dhaka-Chattogram Highway (N1).\", \"t44\": \"This strategic corridor connects four major national highways (N1, N2, N3, N4), creating an uninterrupted pathway for vehicles to traverse from the north/northwest of Dhaka to the southeast without entering the capital\'s congested streets.\", \"t45\": \"12 bridges and 7 flyovers across the route\", \"t46\": \"27 underpasses for cross traffic\", \"t47\": \"5 toll plazas strategically positioned\", \"t48\": \"Partial Opening Success\", \"t49\": \"A 18 km section of the expressway (from Bhogra, Gazipur to Kanchan) was opened on a trial basis in late March 2025 to alleviate traffic for Eid-ul-Fitr travelers.\", \"t50\": \"This section (K3+900 to K22+00) offered toll-free travel during the Eid period, benefiting over 2 million travelers.\", \"t51\": \"Construction Progress\", \"t52\": \"68%\", \"t53\": \"Target completion: July 2025\", \"t54\": \"Key Locations\", \"t55\": \"The Dhaka Bypass Expressway connects several strategic locations, providing efficient access to major highways and urban centers:\", \"t56\": \"Joydebpur (Northern Terminus)\", \"t57\": \"Starting point in Gazipur District that links to National Highway N4 (Dhaka-Mymensingh/Tangail Highways) and N3 (Dhaka-Mymensingh).\", \"t58\": \"Features:\", \"t59\": \"•\", \"t60\": \"Highway link to N4 and N3\", \"t61\": \"•\", \"t62\": \"Major interchange\", \"t63\": \"•\", \"t64\": \"Access to industrial zones\", \"t65\": \"Vogra\", \"t66\": \"First section opened for Eid 2025, where K3+900 marks the beginning of the partial toll collection point.\", \"t67\": \"Features:\", \"t68\": \"•\", \"t69\": \"Toll plaza\", \"t70\": \"•\", \"t71\": \"First operational section\", \"t72\": \"•\", \"t73\": \"Connection to local roads\", \"t74\": \"Kanchan/Purbachal\", \"t75\": \"Interchange providing access to the upcoming Purbachal New Town, enhancing urban expansion.\", \"t76\": \"Features:\", \"t77\": \"•\", \"t78\": \"Link to Purbachal New Town\", \"t79\": \"•\", \"t80\": \"Urban development zone\", \"t81\": \"•\", \"t82\": \"K22+00 marker\", \"t83\": \"Debogram/Bhulta\", \"t84\": \"Mid-route interchange that intersects with the Dhaka-Sylhet Highway (N2), connecting the expressway to eastern regions.\", \"t85\": \"Features:\", \"t86\": \"•\", \"t87\": \"Intersection with N2\", \"t88\": \"•\", \"t89\": \"Service area\", \"t90\": \"•\", \"t91\": \"Eastern route connectivity\", \"t92\": \"Madanpur (Southern Terminus)\", \"t93\": \"Endpoint in Narayanganj District that connects to National Highway N1 (toward Chattogram port) and links to N2 via nearby connections.\", \"t94\": \"Features:\", \"t95\": \"•\", \"t96\": \"Highway link to N1\", \"t97\": \"•\", \"t98\": \"Port city connection\", \"t99\": \"•\", \"t100\": \"Southern interchange\", \"t101\": \"Toll Information\", \"t102\": \"The Dhaka Bypass Expressway operates as a toll road to maintain high service standards and ensure sustainable operations.\", \"t103\": \"Select Vehicle Type\", \"t104\": \"Car\", \"t105\": \"Minibus\", \"t106\": \"Bus\", \"t107\": \"Light Truck\", \"t108\": \"Medium Truck\", \"t109\": \"Heavy Truck\", \"t110\": \"Multi-Axle Truck\", \"t111\": \"Container\", \"t112\": \"Motorcycle\", \"t113\": \"Complete Toll Rate Table\", \"t114\": \"Vehicle Type\", \"t115\": \"Full Distance Toll\", \"t116\": \"Calculation Formula\", \"t117\": \"Partial Section Toll\", \"t118\": \"Large Truck with at least 3 axles (trailer) 15-25 tons\", \"t119\": \"৳\", \"t120\": \"1600\", \"t121\": \"(33.06X18+50)X115%\", \"t122\": \"৳\", \"t123\": \"740\", \"t124\": \"Large/Heavy Truck 2-3 axles, GVW (7+ tons)\", \"t125\": \"৳\", \"t126\": \"1280\", \"t127\": \"(26.45X18+50)X115%\", \"t128\": \"৳\", \"t129\": \"610\", \"t130\": \"Medium Truck with at least 2 axles (5>7 tons)\", \"t131\": \"৳\", \"t132\": \"800\", \"t133\": \"(16.53X18+50)X115%\", \"t134\": \"৳\", \"t135\": \"400\", \"t136\": \"Large Bus (31 seat capacity)\", \"t137\": \"৳\", \"t138\": \"600\", \"t139\": \"(12.4X18+50)X115%\", \"t140\": \"৳\", \"t141\": \"310\", \"t142\": \"Small Truck (3 ton capacity)\", \"t143\": \"৳\", \"t144\": \"480\", \"t145\": \"(9.92X18+50)X115%\", \"t146\": \"৳\", \"t147\": \"260\", \"t148\": \"Minibus, Coaster\", \"t149\": \"৳\", \"t150\": \"360\", \"t151\": \"(7.44X18+50)X115%\", \"t152\": \"৳\", \"t153\": \"210\", \"t154\": \"Microbus\", \"t155\": \"৳\", \"t156\": \"320\", \"t157\": \"(6.61X18+50)X115%\", \"t158\": \"৳\", \"t159\": \"190\", \"t160\": \"Pick Up, Jeep, Wrecker, Converted Jeep, Crane\", \"t161\": \"৳\", \"t162\": \"280\", \"t163\": \"(5.79X18+50)X115%\", \"t164\": \"৳\", \"t165\": \"180\", \"t166\": \"Sedan Car\", \"t167\": \"৳\", \"t168\": \"200\", \"t169\": \"(4.31X18+50)X115%\", \"t170\": \"৳\", \"t171\": \"150\", \"t172\": \"Expressway Facilities\", \"t173\": \"The Dhaka Bypass Expressway offers modern amenities to ensure a safe and comfortable journey for all travelers:\", \"t174\": \"Rest Areas\", \"t175\": \"Two service areas (one in each direction) with amenities for travelers to rest and refresh.\", \"t176\": \"Restrooms and washrooms\", \"t177\": \"Food outlets\", \"t178\": \"Prayer rooms\", \"t179\": \"Toll Stations\", \"t180\": \"Five toll plazas strategically placed to efficiently collect tolls from expressway users.\", \"t181\": \"Multiple toll lanes\", \"t182\": \"Electronic toll collection capability\", \"t183\": \"Clear rate display\", \"t184\": \"Emergency Services\", \"t185\": \"Round-the-clock emergency response services to assist with accidents or breakdowns.\", \"t186\": \"Emergency call points every 2 km\", \"t187\": \"Ambulance services\", \"t188\": \"Towing and recovery\"}','2026-09-05 07:01:17');
INSERT IGNORE INTO `content` (`section_key`, `data`, `updated_at`) VALUES ('page.stakeholders','{\"t1\": \"Project Stakeholders\", \"t2\": \"Meet the organizations and partners behind Bangladesh\'s first fully access-controlled expressway\", \"t3\": \"Investors\", \"t4\": \"Government Parties\", \"t5\": \"Bank Syndication\", \"t6\": \"Project Team\", \"t7\": \"The Dhaka Bypass Expressway is Bangladesh\'s landmark infrastructure project, bringing together a diverse group of stakeholders in a pioneering public-private partnership. Each partner contributes unique expertise, resources, and capabilities to deliver this transformative 48-kilometer expressway.\", \"t8\": \"First Road PPP\", \"t9\": \"in Bangladesh\", \"t10\": \"7 Key Organizations\", \"t11\": \"Working in Partnership\", \"t12\": \"25-Year Concession\", \"t13\": \"Design, Build, Maintain, Finance\", \"t14\": \"Investors\", \"t15\": \"Sichuan Road & Bridge Group Co., Ltd. (SRBG)\", \"t16\": \"Lead Investor & Contractor\", \"t17\": \"1\", \"t18\": \"Lead private investor with 60% equity stake\", \"t19\": \"2\", \"t20\": \"Main Engineering, Procurement, Construction (EPC) contractor\", \"t21\": \"3\", \"t22\": \"Advanced construction technology provider\", \"t23\": \"View Profile\", \"t24\": \"Sichuan Road & Bridge Group (SRBG) is the lead private investor and engineering, procurement, construction (EPC) contractor for the Dhaka Bypass Expressway project. With a 60% equity stake in DBEDC, SRBG brings international expertise in highway construction, acting as the principal builder and operator.\", \"t25\": \"SRBG\'s role includes mobilizing financing, deploying advanced construction technology, and managing operation & maintenance during the concession. The company is fully responsible for the project\'s design and construction, introducing semi-rigid pavement technology and reinforced retaining walls to Bangladesh\'s infrastructure sector.\", \"t26\": \"Under the leadership of their team, SRBG is implementing a full life-cycle operations and maintenance management philosophy. Their expertise has been crucial in implementing the first application of Chinese standards and techniques on a Bangladeshi expressway.\", \"t27\": \"SRBG\'s involvement is a cornerstone of the China-Bangladesh collaboration on this project, demonstrating how Chinese entities can work within Bangladesh\'s PPP policy to deliver infrastructure effectively. The company has also provided training for local engineers and introduced environmentally friendly construction methods.\", \"t28\": \"Member of Shudao Investment Group Co., Ltd. (SDIG)\", \"t29\": \"Employs over 1,000 local workers\", \"t30\": \"Belt and Road Initiative flagship project\", \"t31\": \"Extensive international infrastructure experience\", \"t32\": \"Shamim Enterprise Ltd (SEL)\", \"t33\": \"Major Local Partner\", \"t34\": \"1\", \"t35\": \"Major local private partner with 30% equity stake\", \"t36\": \"2\", \"t37\": \"Provides local knowledge and construction expertise\", \"t38\": \"3\", \"t39\": \"Assists with regulatory compliance and local supply chains\", \"t40\": \"View Profile\", \"t41\": \"Shamim Enterprise Ltd (SEL) is a major local private partner in the DBEDC consortium with a 30% equity stake. As a prominent Bangladeshi construction firm, SEL contributes essential local knowledge, manpower, and support services to the project.\", \"t42\": \"SEL plays a crucial role in navigating domestic requirements such as regulatory compliance and managing local supply chains, ensuring the project adheres to Bangladeshi standards and procedures. The company actively participates in construction and maintenance activities, bringing valuable on-the-ground expertise.\", \"t43\": \"Through its significant stake in the project, SEL helps ensure strong Bangladeshi ownership and representation in the venture\'s success. Working alongside the international partners, SEL facilitates knowledge transfer while contributing to capacity building in Bangladesh\'s infrastructure sector.\", \"t44\": \"Established Bangladeshi construction company\", \"t45\": \"Shamim Ahmed, Company Representative\", \"t46\": \"Experience in large infrastructure projects\", \"t47\": \"Provides extensive local workforce\", \"t48\": \"UDC Construction Ltd\", \"t49\": \"Local Partner\", \"t50\": \"1\", \"t51\": \"Bangladeshi partner with 10% equity stake\", \"t52\": \"2\", \"t53\": \"Provides additional local construction capacity\", \"t54\": \"3\", \"t55\": \"Assists with stakeholder coordination and compliance\", \"t56\": \"View Profile\", \"t57\": \"UDC Construction Ltd (Unique Dream Consultants) is the second Bangladeshi partner in the DBEDC consortium, holding the remaining 10% equity stake. UDC provides additional local construction capacity and expertise to the project.\", \"t58\": \"Together with Shamim Enterprise, UDC represents the Bangladeshi private sector\'s stake in the venture, aiding in on-ground project execution and stakeholder coordination. Both local partners combined hold 40% of DBEDC\'s equity, ensuring a balanced partnership between foreign investment and local participation.\", \"t59\": \"UDC\'s involvement strengthens the consortium\'s ability to navigate local challenges and incorporate Bangladeshi construction practices into the project. Their expertise contributes to effective implementation while supporting capacity building within the domestic construction industry.\", \"t60\": \"Bangladeshi construction and consultancy firm\", \"t61\": \"Specialized in infrastructure development\", \"t62\": \"Experienced in public-private collaboration\", \"t63\": \"Supports local employment and training\", \"t64\": \"Government Parties\", \"t65\": \"Advisory and institutional support\", \"t66\": \"Public-Private Partnership Authority (PPPA)\", \"t67\": \"PPP Facilitator\", \"t68\": \"1\", \"t69\": \"Facilitated project development under PPP modality\", \"t70\": \"2\", \"t71\": \"Approved project in principle in 2012\", \"t72\": \"3\", \"t73\": \"Helped structure the PPP agreement\", \"t74\": \"View Profile\", \"t75\": \"The Public-Private Partnership Authority (PPPA) of Bangladesh has been instrumental in facilitating the Dhaka Bypass Expressway project\'s development under the PPP modality. The PPPA approved the project in principle in 2012 and has since provided critical guidance throughout the process.\", \"t76\": \"PPPA helped structure the PPP agreement, ensuring it met international standards while addressing local requirements. The Authority facilitated the entire process from project conceptualization through contract signing in December 2018, working closely with RHD and other stakeholders.\", \"t77\": \"As this is the first-ever road project in Bangladesh executed via PPP, the PPPA\'s role has been particularly significant. The Authority provides ongoing oversight and policy support, making the Dhaka Bypass Expressway a model for future infrastructure partnerships in the country.\", \"t78\": \"Bangladesh government agency\", \"t79\": \"PPP expert facilitator\", \"t80\": \"Operates under Prime Minister\'s Office\", \"t81\": \"Central agency for PPP project development\", \"t82\": \"Roads and Highways Department\", \"t83\": \"Ministry of Road Transport & Bridges / RHD\", \"t84\": \"1\", \"t85\": \"Public sector client and concession grantor\", \"t86\": \"2\", \"t87\": \"Providing land acquisition and resettlement\", \"t88\": \"3\", \"t89\": \"Contributing viability gap funding (initially ৳224 crore)\", \"t90\": \"View Profile\", \"t91\": \"The Government of Bangladesh, through the Ministry of Road Transport & Bridges and the Roads and Highways Department (RHD), is the public sector client for the Dhaka Bypass Expressway. RHD signed a PPP concession contract in December 2018 with the private consortium to upgrade the 48 km Joydebpur–Debogram–Bhulta–Madanpur road into a four-lane expressway.\", \"t92\": \"The government is responsible for providing land, managing resettlement, and contributing viability gap funding (initially ৳224 crore grant, later revised to ৳674 crore) to ensure the project\'s financial viability. It will also receive the asset back after the 25-year concession period ends.\", \"t93\": \"Under the agreement, the government supports the project with minimum revenue guarantees while allowing the private partners to collect tolls according to a regulated rate structure. This balances public service goals with private sector returns.\", \"t94\": \"The Ministry, through RHD and with the support of the PPP Authority, has provided the enabling conditions for this pioneering project, establishing it as a model for future PPP infrastructure development in Bangladesh.\", \"t95\": \"National highway network manager\", \"t96\": \"Syed Aslam Ali, Project Director (RHD)\", \"t97\": \"Strategic transport infrastructure planner\", \"t98\": \"Asset owner after concession period\", \"t99\": \"Bank Syndication\", \"img1\": \"/friends.webp\", \"t100\": \"Leading investors and technical experts\", \"t101\": \"China Development Bank (CDB) serves as the major foreign lender for the Dhaka Bypass Expressway project. In addition to equity investment from SRBG, the consortium secured a substantial ৳1,614 crore loan from CDB to fund the construction of Bangladesh\'s first fully enclosed expressway.\", \"t102\": \"The financing agreement with CDB was signed in April 2021, completing the project\'s $412 million financing package. CDB\'s long-term loan, alongside BIFFL\'s contribution, enabled financial close and commencement of full-scale construction after initial delays.\", \"t103\": \"This marks one of the first instances of Chinese bank infrastructure financing in a Bangladesh PPP, underlining the international stakeholder dimension. CDB\'s involvement demonstrates China\'s commitment to supporting Bangladesh\'s infrastructure development through financial cooperation as well as technical expertise.\", \"t104\": \"One of China\'s largest policy banks\", \"t105\": \"Supports Belt and Road Initiative projects\", \"t106\": \"Experienced in international infrastructure finance\", \"t107\": \"Long-term development partner in South Asia\", \"t108\": \"China Development Bank (CDB)\", \"t109\": \"Major Foreign Lender\", \"t110\": \"1\", \"t111\": \"Extended ৳1,614 crore loan to DBEDC\", \"t112\": \"2\", \"t113\": \"Financing agreement signed in April 2021\", \"t114\": \"3\", \"t115\": \"Key financial partner for $412 million package\", \"t116\": \"View Profile\", \"t117\": \"Bangladesh Infrastructure Finance Fund Ltd (BIFFL)\", \"t118\": \"Domestic Lender\", \"t119\": \"1\", \"t120\": \"Provided ৳1,075 crore loan to DBEDC\", \"t121\": \"2\", \"t122\": \"First installment of ৳42.5 crore disbursed in April 2022\", \"t123\": \"3\", \"t124\": \"State-owned infrastructure financing company\", \"t125\": \"View Profile\", \"t126\": \"Bangladesh Infrastructure Finance Fund Ltd (BIFFL) is a state-owned infrastructure financing company that has provided significant long-term debt to the Dhaka Bypass Expressway project. Under a 2020 agreement with Asian Development Bank (ADB), BIFFL received a $50 million credit line to support PPP projects.\", \"t127\": \"BIFFL signed a loan facility agreement to re-lend ৳1,075 crore to DBEDC, helping to finance the expressway\'s construction. This domestic financing, backed by ADB, strengthened the project\'s financial structure. In April 2022, BIFFL disbursed the first installment (৳42.5 crore) of this loan to DBEDC.\", \"t128\": \"BIFFL\'s involvement as a local lender is key in bridging the funding gap and ensuring confidence in the project. By mobilizing domestic capital for infrastructure development, BIFFL plays a crucial role in supporting Bangladesh\'s first road PPP project and establishing a template for future initiatives.\", \"t129\": \"Specialized in long-term infrastructure financing\", \"t130\": \"Government of Bangladesh institution\", \"t131\": \"Partnership with international financial institutions\", \"t132\": \"Catalyzing private sector investment\", \"t133\": \"Project Team\", \"t134\": \"Leadership driving the expressway\'s success\", \"t135\": \"Liu Xiaobo\", \"t136\": \"Chairman\", \"t137\": \"Mainly responsible for convening and presiding over shareholders meetings and board meetings. Responsible for overall control of the project.\", \"t138\": \"Chairman\", \"t139\": \"srbgheadoffice@sina.com\", \"t140\": \"Xiao Zhiming\", \"t141\": \"Chief Executive Officer\", \"t142\": \"Oversees all aspects of the project implementation as the CEO of DBEDC. Represents the majority shareholder SRBG and has extensive experience in managing large-scale infrastructure projects.\", \"t143\": \"SRBG Representative\", \"t144\": \"423841503@qq.com\", \"t145\": \"Md. Shafiqul Islam Akand\", \"t146\": \"Chief Operating Officer\", \"t147\": \"The highest-ranking Bangladeshi official in DBEDC, responsible for local operations, regulatory liaison, and ensuring the project meets all local standards and guidelines.\", \"t148\": \"Bangladesh Operations Lead\", \"t149\": \"s_akand@yahoo.com\", \"t150\": \"Project Governance Structure\", \"t151\": \"The Dhaka Bypass Expressway is governed through a structured approach that ensures proper oversight, clear accountability, and effective coordination among all stakeholders.\", \"t152\": \"Board of Directors\", \"t153\": \"The Board comprises representatives from all equity partners (SRBG, SEL, and UDC), with proportional representation based on shareholding. The Board provides strategic direction and major decision approval.\", \"t154\": \"Executive Management\", \"t155\": \"Led by the CEO with support from the COO and General Managers, the executive team handles day-to-day operations, project delivery, stakeholder management, and performance reporting.\", \"t156\": \"Government Oversight\", \"t157\": \"The Project Director from RHD (Syed Aslam Ali) monitors progress, ensures compliance with the concession agreement, and acts as the primary liaison between DBEDC and government agencies.\", \"t158\": \"Discover How This Collaboration Is Transforming Bangladesh\", \"t159\": \"Learn more about how the partnerships behind the Dhaka Bypass Expressway are creating lasting impact through innovative infrastructure development\", \"t160\": \"Explore the Project\", \"t161\": \"Contact Our Team\"}','2026-09-05 07:01:17');
