INSERT IGNORE INTO `media` (`id`, `path`, `width`, `height`, `bytes`, `mime`, `focal_x`, `focal_y`, `alt`, `created_at`, `origin`, `credit`, `original_path`, `in_gallery`) VALUES (1,'/bg-hero.webp',686,386,143706,'image/webp',0.500,0.500,'{\"bn\": \"আকাশ থেকে তোলা এক্সপ্রেসওয়ে, জলাভূমি ও গ্রামের মাঝ দিয়ে বাঁক নিয়ে গেছে, খোলা ক্যারেজওয়েতে যান চলাচল করছে\", \"en\": \"The expressway seen from the air, curving between wetland and villages with traffic on the open carriageway\", \"zh\": \"从空中俯瞰快速路，在湿地与村庄之间蜿蜒，已通车的行车道上有车辆通行\"}','2026-09-05 07:01:18','legacy','DBEDC',NULL,0);
