INSERT IGNORE INTO `page_translations` (`page_id`, `locale`, `title`, `seo_title`, `seo_description`, `og_image`, `status`, `updated_at`) VALUES (2,'en','About DBEDC','','Dhaka Bypass Expressway Development Company builds, operates and maintains the 48 km Dhaka Bypass Expressway between Joydebpur and Madanpur under a public–private partnership.','','published','2026-09-05 07:01:18');
